INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-PRACTICE-2026-SET05','PRACTICE','TOEFL iBT Practice — Set 05 (Full-Length 2026 Format)','Reading 50 · Listening 47 · Writing 12 · Speaking 11','A full-length practice set arranged like the January 2026 TOEFL iBT: Reading (Complete the Words, Read in Daily Life, Read an Academic Passage), Listening (Listen and Choose a Response, Conversation, Announcement, Academic Talk), Writing (Build a Sentence, Write an Email, Write for an Academic Discussion) and Speaking (Listen and Repeat, Take an Interview). Reading passages cover animal migration and magnetic fields, cuneiform grain rations, herd immunity, sign-language grammar, and light pollution; listening items draw on advising, lab loans, campus security, special collections, cafeteria feedback, and housing. 90 minutes of base time matching the published ETS section timings. Every item is originally written for TestPrep; auto-scored items return a TestPrep internal band estimate, not an official ETS score.',NULL,5400,'PUBLISHED','admin');
