(@set05_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["keeps","the","wide","program","community","a","whole","vaccination","safe"]','a wide vaccination program keeps the whole community safe',1,'Subject (a wide vaccination program) + verb (keeps) + object (the whole community) + complement (safe).',100),
(@set05_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["possesses","every","own","its","complete","sign","grammar","language"]','every sign language possesses its own complete grammar',1,'Subject (every sign language) + verb (possesses) + object (its own complete grammar).',101),
