(@set05_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["to","the","asked","students","email","adviser","their","drafts","the"]','the adviser asked the students to email their drafts',1,'Subject (the adviser) + verb (asked) + object (the students) + complement (to email their drafts).',103),
(@set05_exam_id,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["in","the","replaced","battery","technician","the","faulty","the","scale"]','the technician replaced the faulty battery in the scale',1,'Subject (the technician) + verb (replaced) + object (the faulty battery) + place (in the scale).',104),
